90	const severityColors: Record<string, string> = {
91	  critical: "bg-red-50 text-red-700 border-red-200",
92	  warning: "bg-amber-50 text-amber-700 border-amber-200",
93	  info: "bg-blue-50 text-blue-700 border-blue-200",
94	  passed: "bg-emerald-50 text-emerald-700 border-emerald-200",
95	};
