97	export function AgentMessageBubble({ message, isLatest = false }: AgentMessageProps) {
98	  const agent = MOCK_AGENTS.find((a) => a.id === message.agent_id);
99	  const config = typeConfig[message.type];
100	  const Icon = config.icon;
101	
102	  if (!agent) return null;
103	
104	  const time = new Date(message.timestamp).toLocaleTimeString("en-US", {
105	    hour: "numeric",
106	    minute: "2-digit",
107	  });
108	
109	  // Find target agent for handoffs
110	  const targetAgent = message.metadata?.target_agent
111	    ? MOCK_AGENTS.find((a) => a.id === message.metadata?.target_agent)
112	    : null;
113	
114	  return (
115	    <div
116	      className={cn(
117	        "group relative flex gap-3 rounded-xl border p-4 transition-all duration-300",
118	        config.bgColor,
119	        config.borderColor,
120	        isLatest && "animate-fade-in ring-1 ring-primary/10 shadow-sm"
121	      )}
122	    >
123	      {/* Agent Avatar */}
124	      <AgentAvatar
125	        emoji={agent.emoji}
126	        gradient={agent.gradient}
127	        size="sm"
128	        showStatus={false}
129	        className="shrink-0 mt-0.5"
130	      />
131	
132	      {/* Content */}
133	      <div className="flex-1 min-w-0">
134	        {/* Header */}
135	        <div className="flex items-center gap-2 mb-1.5 flex-wrap">
136	          <span className="text-sm font-semibold text-foreground">
137	            {agent.name}
138	          </span>
139	          <span
140	            className={cn(
141	              "inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-medium",
142	              config.bgColor,
143	              config.iconColor
144	            )}
145	          >
146	            <Icon className="h-2.5 w-2.5" />
147	            {config.label}
148	          </span>
149	          {message.metadata?.severity && (
150	            <Badge
151	              variant="outline"
152	              className={cn(
153	                "text-[10px] uppercase",
154	                severityColors[message.metadata.severity]
155	              )}
156	            >
157	              {message.metadata.severity}
158	            </Badge>
159	          )}
160	          <span className="text-[10px] text-muted-foreground ml-auto">
161	            {time}
162	          </span>
163	        </div>
164	
165	        {/* Message body */}
166	        <div className="text-sm text-foreground/90 leading-relaxed whitespace-pre-line">
167	          {message.content}
168	        </div>
169	
170	        {/* Metadata */}
171	        {(message.metadata?.confidence || message.metadata?.impact || targetAgent) && (
172	          <div className="flex items-center gap-3 mt-2 pt-2 border-t border-slate-100 flex-wrap">
173	            {message.metadata?.confidence && (
174	              <span className="text-[10px] text-muted-foreground">
175	                Confidence:{" "}
176	                <span className="font-medium text-foreground">
177	                  {message.metadata.confidence}%
178	                </span>
179	              </span>
180	            )}
181	            {message.metadata?.impact && (
182	              <span className="text-[10px] text-muted-foreground">
183	                Impact:{" "}
184	                <span className="font-medium text-green-600">
185	                  {message.metadata.impact}
186	                </span>
187	              </span>
188	            )}
189	            {targetAgent && (
190	              <span className="text-[10px] text-muted-foreground flex items-center gap-1">
191	                Handed off to{" "}
192	                <span className="font-medium text-foreground">
193	                  {targetAgent.emoji} {targetAgent.name}
194	                </span>
195	              </span>
196	            )}
197	          </div>
198	        )}
199	      </div>
200	    </div>
201	  );
202	}
